        return self._call('generate_world', {'expectedRevision': expected_revision, 'seed': seed, 'coverage': coverage, 'rainfall': rainfall, 'temperature': temperature, 'population': population, 'landmarkDensity': landmark_density, 'pollution': pollution, 'requestId': request_id, 'waitSeconds': wait_seconds})

